import sys, random, math; sys.path.insert(0,'.')
import layout
from layout import *
layout.GAP=2.36
base=dict(cx=-5.0,ez=-9.0,gz=[-13.6,-12.6,-11.6],belt=(-6.3,-14.0),up=[(-6.9,-13.6),(-3.2,-12.2),(-6.9,-11.4)],jam0=(-2.0,-13.7),cannon=(-10.3,-15.0),chute=(-8.8,-13.2))
keys=['belt','p','t','g','jam0','cannon','chute']
def cfg_of(v):
    c=dict(base); c['belt']=v[0]; c['up']=[v[1],v[2],v[3]]; c['jam0']=v[4]; c['cannon']=v[5]; c['chute']=v[6]; return c
v0=[base['belt'],base['up'][0],base['up'][1],base['up'][2],base['jam0'],base['cannon'],base['chute']]
def cost(v): return sum(d(a,b) for a,b in zip(v,v0))
def score(v):
    return len(check(cfg_of(v)))
random.seed(int(sys.argv[1]) if len(sys.argv)>1 else 1)
best=None
for rs in range(30):
    v=list(v0); cur=score(v)
    for it in range(4000):
        i=random.randrange(len(v)); s=random.choice([0.1,0.3,0.6])
        n=list(v); n[i]=(round(v[i][0]+random.uniform(-s,s),2),round(v[i][1]+random.uniform(-s,s),2))
        sc=score(n)
        if sc<=cur: v,cur=n,sc
        if cur==0: break
    if cur==0:
        # shrink cost
        for it in range(6000):
            i=random.randrange(len(v)); s=random.choice([0.05,0.15])
            n=list(v); n[i]=(round(v[i][0]+random.uniform(-s,s),2),round(v[i][1]+random.uniform(-s,s),2))
            if score(n)==0 and cost(n)<=cost(v): v=n
        if best is None or cost(v)<best[0]: best=(cost(v),v); print(best,flush=True)
